package com.rustymediclabs.wherewasi;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Each non-empty note line is a task; duplicate lines have separate identities. */
final class JournalChecklist
{
	static final class Task
	{
		final String id;
		final String text;
		Task(String id, String text) { this.id = id; this.text = text; }
	}

	static List<Task> tasks(String note)
	{
		List<Task> result = new ArrayList<>();
		Map<String, Integer> occurrences = new HashMap<>();
		if (note == null) { return result; }
		for (String line : note.split("\\R"))
		{
			String text = line.trim();
			if (text.isEmpty()) { continue; }
			int occurrence = occurrences.merge(text, 1, Integer::sum);
			String id = Base64.getEncoder().encodeToString(text.getBytes(StandardCharsets.UTF_8)) + ":" + occurrence;
			result.add(new Task(id, text));
		}
		return result;
	}

	static Set<String> decode(String value)
	{
		Set<String> result = new HashSet<>();
		if (value != null)
		{
			for (String id : value.split("\n")) { if (!id.isEmpty()) { result.add(id); } }
		}
		return result;
	}

	static String encode(Set<String> done)
	{
		return String.join("\n", new java.util.TreeSet<>(done));
	}

	static String next(String note, Set<String> done)
	{
		List<Task> tasks = tasks(note);
		for (Task task : tasks) { if (!done.contains(task.id)) { return task.text; } }
		return tasks.isEmpty() ? "Leave yourself a next step" : "All steps done — what's next?";
	}
}

package com.rustymediclabs.wherewasi;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/** Local journal cue only; never intercepts logout or game input. */
final class JournalReminderOverlay extends OverlayPanel
{
	private final Client client;
	private final WhereWasIConfig config;
	private final WhereWasIPlugin plugin;

	@Inject
	JournalReminderOverlay(Client client, WhereWasIConfig config, WhereWasIPlugin plugin)
	{
		super(plugin);
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(220, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.screenReminder() || client.getGameState() != GameState.LOGGED_IN) { return null; }
		panelComponent.getChildren().add(LineComponent.builder().left("Where Was I?")
			.leftColor(new Color(230, 183, 92)).build());
		panelComponent.getChildren().add(LineComponent.builder().left(plugin.getReminderText()).build());
		panelComponent.getChildren().add(LineComponent.builder().left("Before logout: update your journal")
			.leftColor(new Color(177, 163, 141)).build());
		return super.render(graphics);
	}
}

package com.rustymediclabs.wherewasi;

/** Version-one saved location, independent of the client and Swing. */
final class LastVisit
{
	final int x, y, plane, world;
	final long savedAt;

	LastVisit(int x, int y, int plane, int world, long savedAt)
	{
		this.x = x;
		this.y = y;
		this.plane = plane;
		this.world = world;
		this.savedAt = savedAt;
	}

	String encode()
	{
		return x + "," + y + "," + plane + "," + world + "," + savedAt;
	}

	static LastVisit decode(String value)
	{
		if (value == null) { return null; }
		String[] parts = value.split(",", -1);
		if (parts.length != 5) { return null; }
		try
		{
			LastVisit visit = new LastVisit(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]),
				Integer.parseInt(parts[2]), Integer.parseInt(parts[3]), Long.parseLong(parts[4]));
			return visit.x >= 0 && visit.y >= 0 && visit.plane >= 0 && visit.plane <= 3
				&& visit.world > 0 && visit.savedAt > 0 ? visit : null;
		}
		catch (NumberFormatException ignored) { return null; }
	}
}

package com.rustymediclabs.wherewasi;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringJoiner;

/** Stable session IDs let checkpoints replace the same session instead of duplicating it. */
final class SessionHistory
{
	static final int LIMIT = 20;
	static final class Entry
	{
		final long id;
		final SessionRecap recap;
		Entry(long id, SessionRecap recap) { this.id = id; this.recap = recap; }
	}
	private final List<Entry> entries;

	private SessionHistory(List<Entry> entries) { this.entries = Collections.unmodifiableList(entries); }
	List<Entry> entries() { return entries; }

	SessionHistory with(long id, SessionRecap recap)
	{
		List<Entry> result = new ArrayList<>();
		result.add(new Entry(id, recap));
		for (Entry entry : entries)
		{
			if (entry.id != id && result.size() < LIMIT) { result.add(entry); }
		}
		return new SessionHistory(result);
	}

	String encode()
	{
		StringJoiner result = new StringJoiner("\n");
		for (Entry entry : entries) { result.add(entry.id + "|" + entry.recap.encode()); }
		return result.toString();
	}

	static SessionHistory decode(String text)
	{
		List<Entry> result = new ArrayList<>();
		if (text != null)
		{
			for (String line : text.split("\n"))
			{
				String[] parts = line.split("\\|", 2);
				if (parts.length != 2) { continue; }
				try
				{
					long id = Long.parseLong(parts[0]);
					SessionRecap recap = SessionRecap.decode(parts[1]);
					if (id > 0 && recap != null && result.stream().noneMatch(e -> e.id == id) && result.size() < LIMIT)
					{
						result.add(new Entry(id, recap));
					}
				}
				catch (NumberFormatException ignored) { /* Skip damaged entries, retain valid history. */ }
			}
		}
		return new SessionHistory(result);
	}
}

package com.rustymediclabs.wherewasi;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.StringJoiner;
import net.runelite.api.Skill;

/** Immutable checkpoint of XP gained while this plugin was enabled. */
final class SessionRecap
{
	final long endedAt;
	final Map<Skill, Integer> gains;
	final boolean tracked;

	private SessionRecap(long endedAt, Map<Skill, Integer> gains, boolean tracked)
	{
		this.endedAt = endedAt;
		EnumMap<Skill, Integer> copy = new EnumMap<>(Skill.class);
		copy.putAll(gains);
		this.gains = Collections.unmodifiableMap(copy);
		this.tracked = tracked;
	}

	static SessionRecap legacy(long time)
	{
		return new SessionRecap(time, Collections.emptyMap(), false);
	}

	static boolean experienceReady(int[] values)
	{
		if (values == null) { return false; }
		for (int value : values) { if (value > 0) { return true; } }
		return false;
	}

	static SessionRecap capture(int[] baseline, int[] current, long time)
	{
		Map<Skill, Integer> gains = new EnumMap<>(Skill.class);
		Skill[] skills = Skill.values();
		for (int i = 0; i < Math.min(skills.length, Math.min(baseline.length, current.length)); i++)
		{
			int gain = current[i] - baseline[i];
			if (gain > 0) { gains.put(skills[i], gain); }
		}
		return new SessionRecap(time, gains, true);
	}

	String encode()
	{
		StringJoiner values = new StringJoiner(",");
		gains.forEach((skill, gain) -> values.add(skill.name() + "=" + gain));
		return endedAt + ";" + values;
	}

	static SessionRecap decode(String text)
	{
		if (text == null) { return null; }
		String[] parts = text.split(";", -1);
		if (parts.length != 2) { return null; }
		try
		{
			long time = Long.parseLong(parts[0]);
			if (time <= 0) { return null; }
			Map<Skill, Integer> gains = new EnumMap<>(Skill.class);
			if (!parts[1].isEmpty())
			{
				for (String entry : parts[1].split(",", -1))
				{
					String[] pair = entry.split("=", -1);
					if (pair.length != 2) { return null; }
					int gain = Integer.parseInt(pair[1]);
					if (gain <= 0) { return null; }
					try { gains.put(Skill.valueOf(pair[0]), gain); }
					catch (IllegalArgumentException ignored) { /* Future skill: retain other known gains. */ }
				}
			}
			return new SessionRecap(time, gains, true);
		}
		catch (NumberFormatException ignored) { return null; }
	}
}

package com.rustymediclabs.wherewasi;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(WhereWasIConfig.GROUP)
